import dev.hua.ptcglive.engine.*;
import dev.hua.ptcglive.engine.field.*;
import java.util.*;

public final class StarterDeck100CounterEntryTest {
    static final UUID A=StarterDeck100PokemonTest.A,B=StarterDeck100PokemonTest.B;
    static String id(int n){return StarterDeck100PokemonTest.id(n);}
    static void check(boolean ok,String why){StarterDeck100PokemonTest.check(ok,why);}
    public static void main(String[] args){for(int damage:List.of(0,50,120,150))horn(damage);psychic();for(int prizes:List.of(0,1))jealous(prizes);for(String mode:List.of("ACCEPT","DECLINE","DISCARD","DISABLE_AFTER"))doll(mode);opening();System.out.println("StarterDeck100CounterEntryTest passed: remaining-HP counters never heal, no WR, Energy units, prizes taken, optional hand-entry protection, expiry, discard/opening exclusions and damage/effect distinction");}
    static void horn(int damage){var m=StarterDeck100PokemonTest.game(163);var target=m.benchPokemonView(B).getFirst().pokemonId();if(damage>0)m.placeDamageCountersByEffect(A,B,target,damage/10);StarterDeck100PokemonTest.attack(m,0);StarterDeck100PokemonTest.choosePokemon(m,target);check(StarterDeck100PokemonTest.view(m,B,target).damage()==Math.max(120,damage),"Libra Horn wrong remaining HP or healed target");check(m.lastAttack().finalDamage()==0&&m.activePokemonView(B).damage()==0,"Libra Horn became attack damage or targeted Active");}
    static void psychic(){var m=StarterDeck100PokemonTest.game(163,1,"sm1_en_136");var e=m.privateView(A).deck().stream().filter(c->c.definitionId().equals("sm1_en_136")).findFirst().orElseThrow();m.attachEnergyByEffect(A,A,EffectSourceZone.DECK,e.instanceId(),B,m.activePokemonView(B).pokemonId());StarterDeck100PokemonTest.attack(m,1);check(m.lastAttack().finalDamage()==120,"Psychic counted cards rather than units");}
    static void jealous(int prizes){var m=StarterDeck100PokemonTest.game(197);if(prizes>0){m.endTurn(A);m.knockOutPokemonByEffect(B,A,m.benchPokemonView(A).getFirst().pokemonId());StarterDeck100CombatTest.settleKnockouts(m);m.endTurn(B);}int taken=6-m.privateView(B).prizes().size();StarterDeck100PokemonTest.attack(m,0);check(m.activePokemonView(B).damage()==taken*30&&m.lastAttack().finalDamage()==0,"Jealous Eyes used prizes remaining or attack damage");}
    static void doll(String mode){var m=StarterDeck100PokemonTest.game(1,1,id(197));var card=StarterDeck100PokemonTest.hand(m,id(197));if(mode.equals("DISCARD")){m.discardHandCardsByEffect(A,A,List.of(card.instanceId()));m.putBasicPokemonFromDiscardToBenchByEffect(A,A,card.instanceId());check(m.triggerOrderPrompt()==null,"discard entry triggered Dummy Doll");}else{m.playBasicPokemonToBench(A,card.instanceId());var p=m.triggerOrderPrompt();check(p!=null&&p.optionalDecision()&&p.choosingPlayer().equals(A),"missing optional hand entry");m.decideTriggeredEffect(A,p.id(),!mode.equals("DECLINE"));}m.switchActiveByEffect(A,A,card.instanceId());if(mode.equals("DISABLE_AFTER"))m.disableAbilityEffectsByEffect(A,A,card.instanceId());m.endTurn(A);StarterDeck100GuardTest.attackOpponent(m,1,0);boolean guarded=mode.equals("ACCEPT")||mode.equals("DISABLE_AFTER");check(m.lastAttack().finalDamage()==(guarded?0:50),"Dummy Doll origin/optional/granted-effect mismatch: "+mode);m.endTurn(A);m.attack(B,"leaf-drain");check(m.lastAttack().finalDamage()==50,"Dummy Doll persisted beyond opponent turn end");}
    static void opening(){var m=StarterDeck100PokemonTest.game(197);check(m.triggerOrderPrompt()==null,"opening triggered Dummy Doll");m.endTurn(A);StarterDeck100GuardTest.attackOpponent(m,1,0);check(m.lastAttack().finalDamage()==50,"opening Pokemon acquired hand-entry protection");}
}
